/* ---------- chapter 20 decisions ---------- */
const budOK20=S=>S.ya<=2473;
const DEC_IN20=[
{id:'c20_naga',deck:'child',w:8,ch:20,a:[4,9],t:X('นมสำหรับนาค','Milk for the naga'),
 x:X('ยายพาคุณไปที่จอมปลวกหลังหมู่บ้าน วางถ้วยนมไว้ข้างรู แล้วกระซิบว่าข้างล่างนั้นมีนาคอาศัยอยู่ ถ้าเลี้ยงดี นาคจะให้ฝนตกตามฤดู','Grandmother takes you to the anthill behind the village, sets a cup of milk by the hole, and whispers that a naga lives below. Treat it well, and it will bring the rains on time.'),
 n:X('นาคเป็นงูศักดิ์สิทธิ์ที่คุมน้ำและฝน ชาวบ้านบูชามาก่อนศาสนาพุทธและเชน และทั้งสองศาสนาก็รับนาคเข้าไปในเรื่องเล่าของตน ในพระสูตร พญานาคมุจลินท์แผ่พังพานกันฝนให้พระพุทธเจ้า ราวบันไดรูปนาคในวัดไทยทุกวันนี้ก็สืบมาจากความเชื่อนี้','Nagas were sacred serpents who ruled water and rain. Villagers worshipped them before Buddhism or Jainism, and both took nagas into their own stories: in the discourses the naga king Mucalinda spreads his hood to shelter the Buddha from the rain. The naga stair-rails of Thai temples descend from this belief.'),
 o:[opt(X('วางดอกไม้ไว้ด้วย','Leave a flower too'),S=>{fa20(S,'yak',1);fx({b:3});return X('เช้าวันรุ่งขึ้นถ้วยนมว่าง คุณไม่รู้ว่าเป็นนาคหรือแมว','By morning the cup is empty. You don’t know whether it was the naga or the cat.')}),
    opt(X('แอบนั่งรอดูนาค','Hide and wait to see the naga'),S=>{fa20(S,'yak',.5);fx({kn:2});return X('คุณเห็นงูเห่าตัวหนึ่ง และวิ่งกลับบ้านเร็วที่สุดในชีวิต','You see a cobra, and run home faster than you have ever run.')})]},
{id:'c20_yak',deck:'child',w:7,ch:20,a:[5,10],t:X('ยักษ์ใต้ต้นไทร','The yakkha under the banyan'),
 x:X('ใต้ต้นไทรใหญ่กลางหมู่บ้านมีแท่นหินที่ชาวบ้านทาสีแดงและวางข้าว ผู้ใหญ่บอกว่ายักษ์ที่อยู่ในต้นไม้คุ้มครองหมู่บ้าน ถ้าทำให้โกรธ จะมีคนป่วย','Under the great banyan in the village is a stone platform the villagers smear with red and heap with rice. The grown-ups say the yakkha in the tree protects the village; anger it, and someone will fall sick.'),
 n:X('ยักษ์ในอินเดียโบราณไม่ได้เป็นปีศาจเสมอไป หลายตนเป็นเทพประจำต้นไม้ เมือง และทรัพย์สมบัติ รูปปั้นยักษ์หินขนาดใหญ่ยุคนี้ยังเหลืออยู่ ศาสนาพุทธรับยักษ์เป็นผู้พิทักษ์ ท้าวเวสสุวรรณที่คนไทยนิยมบูชาก็คือราชาของยักษ์ และยักษ์ที่ยืนเฝ้าประตูวัดไทยก็สืบเชื้อสายมาจากความเชื่อนี้','Yakkhas in ancient India were not always demons; many were gods of trees, towns and treasure, and great stone yakkha statues from this age survive. Buddhism took them in as guardians. Thao Wessuwan, whom many Thais worship, is the king of the yakkhas, and the giants guarding Thai temple gates descend from this belief.'),
 o:[opt(X('ไหว้ยักษ์ทุกครั้งที่เดินผ่าน','Bow to the yakkha every time you pass'),S=>{fa20(S,'yak',1);fx({b:2});return X('คุณเชื่อว่ามันช่วยให้คุณหายไข้ครั้งหนึ่ง ใครจะรู้','You believe it helped you through a fever once. Who knows?')}),
    opt(X('ปีนต้นไทรเล่น','Climb the banyan'),S=>{fx({sv:2,b:2});return X('ไม่มีอะไรเกิดขึ้น นอกจากแม่ดุ ซึ่งน่ากลัวกว่ายักษ์','Nothing happens except a scolding from Mother, which is scarier than any yakkha.')})]},
{id:'c20_coin',deck:'child',w:5,ch:20,a:[5,11],t:X('เหรียญแปลกๆ','A strange coin'),
 x:X('พ่อให้คุณดูแผ่นเงินเล็กๆ ที่บิดเบี้ยว มีรอยตอกเป็นรูปดวงอาทิตย์ ช้าง และสัญลักษณ์ที่คุณไม่รู้จัก พ่อบอกว่าแผ่นนี้แลกข้าวได้หนึ่งกระบุง','Father shows you a small bent piece of silver punched with a sun, an elephant and signs you don’t know. He says it will buy a basket of rice.'),
 n:X('เหรียญตอกตราของอินเดียเริ่มใช้ราวศตวรรษที่ 6–5 ก่อนคริสตกาล ไม่นานหลังจากเหรียญแรกของโลกเกิดในลิเดีย และราวเดียวกับที่จีนเริ่มใช้เหรียญ เงินตราช่วยให้การค้าและเมืองเติบโต และทำให้พ่อค้ามีเงินเหลือพอจะอุปถัมภ์นักบวช นักประวัติศาสตร์หลายคนเห็นว่านี่เป็นเหตุหนึ่งที่สำนักนักบวชพเนจรเฟื่องฟูในยุคนี้','India’s punch-marked coins began around the 6th–5th century BCE, not long after the world’s first coins in Lydia, and around the time China began using coins. Money helped trade and towns grow, and left merchants with wealth to support ascetics; many historians see this as one reason wandering schools flourished in this age.'),
 o:[opt(X('เก็บไว้ใต้หมอน','Keep it under your pillow'),S=>{S.ag+=1;fx({b:2});return X('คุณนับมันทุกคืน มันก็ยังมีแค่หนึ่งเหรียญ','You count it every night. It is still only one coin.')}),
    opt(X('ถามว่าทำไมแผ่นเงินถึงมีค่า','Ask why a bit of silver is worth anything'),S=>{fx({kn:3});return X('พ่อคิดนานแล้วตอบว่า “เพราะทุกคนเชื่อว่ามันมีค่า” คำตอบนี้ยังจริงอยู่สองพันห้าร้อยปีต่อมา','Father thinks a long time and says, “Because everyone believes it is.” The answer is still true 2,500 years later.')})]},
{id:'c20_rains',deck:'child',w:6,ch:20,a:[5,12],cond:budOK20,t:X('นักบวชที่หยุดเดินตอนฝนตก','Ascetics who stop walking in the rains'),
 x:X('พอฝนแรกมา นักบวชที่เคยเดินผ่านหมู่บ้านทุกวันหยุดเดินทาง และพักอยู่ในที่เดียวตลอดฤดูฝน ผู้ใหญ่บอกว่าเพราะชาวบ้านเคยบ่นว่าพวกเขาเดินเหยียบต้นกล้าและสัตว์ตัวเล็กๆ','When the first rains come, the ascetics who passed through every day stop travelling and stay in one place for the whole wet season. The grown-ups say it is because villagers once complained that they trampled the seedlings and the little creatures.'),
 n:X('พระวินัยเล่าว่าชาวบ้านติเตียนว่าภิกษุเดินเหยียบหญ้าอ่อนและสัตว์ตัวเล็กในฤดูฝน ขณะที่นักบวชนิกายอื่นหยุดอยู่กับที่ พระพุทธเจ้าจึงให้ภิกษุจำพรรษา ธรรมเนียมนี้คือวันเข้าพรรษาที่คนไทยยังถือทุกปี','The Vinaya says lay people complained that monks trampled young grass and small creatures in the rains while ascetics of other schools stayed put, so the Buddha told monks to keep the rains retreat. It is the origin of Khao Phansa, still kept in Thailand every year.'),
 o:[opt(X('ช่วยสร้างกระท่อมให้นักบวช','Help build a hut for the ascetics'),S=>{fa20(S,'bud',.5);fx({cr:2,so:2});return X('ทั้งฤดูฝน คุณได้ยินเสียงสวดจากกระท่อมที่คุณช่วยมุงหลังคา','All through the rains you hear chanting from the hut you helped to thatch.')}),
    opt(X('ระวังไม่เหยียบไส้เดือน','Take care not to tread on the worms'),S=>{fa20(S,'jain',.3);fx({kn:2,b:1});return X('คุณเดินช้าลงมาก จนแม่ถามว่าป่วยหรือเปล่า','You walk so slowly that Mother asks if you are ill.')})]},
{id:'c20_hare',deck:'child',w:6,ch:20,a:[4,10],t:X('กระต่ายบนดวงจันทร์','The hare in the moon'),
 x:X('ยายเล่าว่า นานมาแล้ว กระต่ายตัวหนึ่งไม่มีอะไรจะให้พราหมณ์ที่หิวโหย จึงกระโดดเข้ากองไฟเพื่อให้เขากินเนื้อตัวเอง พราหมณ์คนนั้นคือเทพที่แปลงกายมา จึงวาดรูปกระต่ายไว้บนดวงจันทร์ให้ทุกคนเห็น','Grandmother tells how, long ago, a hare had nothing to give a hungry Brahmin, so it leapt into the fire to offer its own flesh. The Brahmin was a god in disguise, who drew the hare on the moon for everyone to see.'),
 n:X('นี่คือสสชาดก นิทานเรื่องอดีตชาติของพระพุทธเจ้า ✦ ชาดกหลายเรื่องเป็นนิทานพื้นบ้านที่เล่ากันอยู่ก่อนแล้ว แล้วถูกเล่าใหม่ให้เป็นเรื่องของพระโพธิสัตว์ คนไทยยังเห็น “กระต่ายในดวงจันทร์” จากนิทานนี้','This is the Sasa Jataka, a tale of one of the Buddha’s past lives ✦. Many Jatakas were folk tales already being told, retold as stories of the Bodhisatta. Thais still see “the hare in the moon” from this tale.'),
 o:[opt(X('มองหากระต่ายบนดวงจันทร์','Look for the hare on the moon'),S=>{fx({b:4});return X('คุณเห็นหูยาวๆ สองข้าง และจะเห็นมันไปตลอดชีวิต','You see two long ears, and you will see them for the rest of your life.')}),
    opt(X('ถามว่ากระต่ายเจ็บไหม','Ask whether the hare was hurt'),S=>{fx({kn:2,so:1});return X('ยายบอกว่าไฟไม่ร้อนเลยสำหรับคนที่ให้ด้วยใจจริง คุณยังไม่เชื่อ แต่ชอบเรื่องนี้','Grandmother says the fire was not hot at all for one who gave with a true heart. You don’t quite believe it, but you love the story.')})]},
{id:'c20_veda',deck:'child',w:8,ch:20,a:[7,13],cond:S=>S.var20==='brah'&&S.sex==='m',t:X('ท่องทีละพยางค์','One syllable at a time'),
 x:X('ครูให้คุณนั่งตรงข้าม แล้วท่องบทสวดพระเวททีละสองคำ คุณต้องท่องตามให้ตรงทั้งเสียงสูงต่ำ เมื่อจำได้แล้ว ต้องท่องแบบสลับคำไปมาอีกหลายแบบ จนผิดไม่ได้แม้แต่พยางค์เดียว','Your teacher sits facing you and chants the Vedic hymns two words at a time. You must repeat them with every rise and fall of pitch, and once you know them, chant them again in several patterns of shuffled words, until not one syllable can go wrong.'),
 n:X('พราหมณ์ท่องพระเวทด้วยวิธีที่ซับซ้อนมาก เช่นท่องทีละคำ ท่องเป็นคู่ไปข้างหน้าและถอยหลัง ซึ่งช่วยให้ฤคเวทถูกส่งต่อด้วยปากได้แม่นยำอย่างน่าทึ่งกว่าสามพันปี ยูเนสโกยกย่องการสวดพระเวทเป็นมรดกทางวัฒนธรรมที่จับต้องไม่ได้ วิธีท่องจำแบบนี้อาจเป็นแบบอย่างให้นักบวชพุทธที่จำคำสอนโดยไม่มีการเขียน','Brahmins chanted the Vedas in elaborate patterns: word by word, in pairs forwards and backwards. This helped the Rigveda pass by mouth with astonishing accuracy for more than three thousand years, and UNESCO honours Vedic chanting as intangible heritage. Such methods may have set the example for Buddhist monks who kept their teachings without writing.'),
 o:[opt(X('ท่องจนเสียงแหบ','Recite until your voice is hoarse'),S=>{S.rec20=(S.rec20||0)+8;fa20(S,'veda',1);fx({kn:4,h:-1});return X('คืนนั้นคุณท่องในฝันด้วย และไม่ผิดสักพยางค์','That night you recite in your dreams too, without a single mistake.')}),
    opt(X('ถามว่าคำเหล่านี้แปลว่าอะไร','Ask what the words mean'),S=>{fa20(S,'veda',.5);fx({kn:2});return X('ครูบอกว่าความหมายสำคัญ แต่เสียงสำคัญกว่า เสียงผิด พิธีก็เสีย','The teacher says meaning matters, but sound matters more: a wrong sound spoils the rite.')})]},
{id:'y20_marry',deck:'youth',w:5,ch:20,a:[13,26],cond:S=>!S.partner&&!S.monk20&&S.car!=='samana'&&S.cls!=='slave'&&(S.sex==='f'||S.age>=18),t:X('งานแต่งงาน','The wedding'),
 xf:S=>S.sex==='f'?X('ครอบครัวจัดการแต่งงานให้คุณกับชายจากกลุ่มเดียวกัน หมอดูเลือกฤกษ์ คุณกับเจ้าบ่าวเดินรอบกองไฟเจ็ดก้าว แล้วย้ายไปอยู่บ้านครอบครัวสามี','Your family arranges your marriage to a man of your own birth group. An astrologer picks the day; you and the groom take seven steps around the fire, and you move to his family’s house.'):X('ครอบครัวของคุณกับอีกครอบครัวในกลุ่มเดียวกันตกลงเรื่องแต่งงาน หมอดูเลือกฤกษ์ และเจ้าสาวจะย้ายมาอยู่บ้านของคุณ','Your family and another of your birth group agree on a marriage. An astrologer picks the day, and the bride will come to live in your family’s house.'),
 n:X('การเดินเจ็ดก้าวรอบไฟศักดิ์สิทธิ์เป็นพิธีแต่งงานแบบพระเวทที่ยังใช้ในอินเดียทุกวันนี้ ครอบครัวมักเลือกคู่ในกลุ่มกำเนิดเดียวกัน พระสูตรพุทธหลายเรื่องเล่าถึงสามีภรรยาที่เป็นผู้ใจบุญคู่กัน และสอนหน้าที่ของสามีต่อภรรยาและภรรยาต่อสามี','The seven steps around the sacred fire are a Vedic wedding rite still used in India today. Families usually chose partners from the same birth group. Several Buddhist discourses tell of married couples who were devoted lay followers together, and teach the duties of husband to wife and wife to husband.'),
 o:[opt(X('ตกลง','Agree'),S=>{S.partner=1;ms(X('สร้างครอบครัวใหม่','Founded a new household'));mkP('partner');fa20(S,'veda',.5);fx({b:6});return X('เสียงกลองและขลุ่ยดังทั้งคืน บ้านใหม่มีกลิ่นควันไฟพิธีไปอีกหลายวัน','Drums and flutes play all night, and the new house smells of the ritual fire for days.')}),
    opt(X('ขอรอไปก่อน','Ask to wait'),S=>{fx({b:-2,so:-1});return X('ครอบครัวไม่พอใจ แต่ยอมรอ ป้าๆ ในหมู่บ้านพูดถึงเรื่องนี้ไปอีกนาน','Your family is displeased but agrees to wait. The village aunts talk about it for a long time.')})]},
{id:'y20_debate',deck:'youth',w:7,ch:20,a:[14,30],cond:S=>S.ya>=2420,t:X('ศาลาแห่งความอยากรู้','The hall of curiosity'),
 x:X('ที่ศาลาริมเมือง นักบวชจากหลายสำนักมาพักและโต้วาทีกันทุกเย็น คนหนึ่งห่มผ้าทอจากผมคน บอกว่าตายแล้วก็จบ ไม่มีชาติหน้า อีกคนเปลือยกาย บอกว่าชะตากำหนดไว้หมดแล้ว คนที่สามสอนให้ไม่ทำร้ายสิ่งใดเลย คนที่สี่พูดถึงทางสายกลาง','At the hall on the edge of town, ascetics of many schools stay and debate every evening. One, wrapped in a blanket woven of human hair, says death is the end: there is no next life. Another, naked, says all is fixed by fate. A third teaches harming nothing at all. A fourth speaks of a middle way.'),
 n:X('คัมภีร์บาลีเรียกที่พักแบบนี้ว่า “กุตูหลศาลา” ศาลาแห่งความอยากรู้ สามัญญผลสูตรเอ่ยชื่อครูคู่แข่งหกคนในยุคพระพุทธเจ้า รวมทั้งอชิตะ เกสกัมพล ผู้สอนว่าไม่มีชาติหน้า มักขลิ โคศาล และนิครนถ์ นาฏบุตร หรือมหาวีระ คนทั่วไปฟังหลายสำนักและให้อาหารนักบวชทุกสำนัก ไม่ได้เลือกศาสนาเดียวแบบทุกวันนี้','The Pali texts call such places kutuhalasala, “halls of curiosity”. The Samaññaphala Sutta names six rival teachers of the Buddha’s time, including Ajita of the hair blanket, who taught there is no next life, Makkhali Gosala, and the Nigantha Nataputta, Mahavira. Ordinary people listened to many schools and fed ascetics of all of them; they did not pick one religion as people often do today.'),
 o:[opt(X('เชื่อคนห่มผ้าผม: ตายแล้วจบ','Believe the hair-blanket man: death is the end'),S=>{fa20(S,'lok',1);fx({b:2,kn:1});return X('คุณตัดสินใจกินให้อร่อยวันนี้ เพราะพรุ่งนี้อาจไม่มี','You decide to enjoy your dinner today, since tomorrow may not come.')}),
    opt(X('เชื่อนักบวชเปลือย: ชะตากำหนดทุกอย่าง','Believe the naked one: fate decides all'),S=>{fa20(S,'aji',1);fx({b:1});return X('คุณเลิกกังวลเรื่องสอบ เพราะผลถูกกำหนดไว้แล้ว ซึ่งทำให้ผลออกมาไม่ดี','You stop worrying about your lessons, since the outcome is fixed. Which is why it turns out badly.')}),
    opt(X('ฟังครูที่สอนไม่ทำร้ายสิ่งใด','Listen to the teacher of harmlessness'),S=>{fa20(S,'jain',1);fx({kn:2,so:1});return X('คุณเริ่มกรองน้ำก่อนดื่ม เผื่อมีสัตว์ตัวเล็กอยู่ข้างใน','You start straining your water before you drink, in case tiny creatures are inside.')}),
    opt(X('ฟังเรื่องทางสายกลาง','Listen to the middle way'),S=>{fa20(S,'bud',1);fx({kn:2,b:1});return X('ไม่สุดโต่งทางไหนเลย คุณคิดว่าฟังดูง่าย แล้วพบว่ายากที่สุด','Not too far either way. It sounds easy; you find it is the hardest of all.')})]},
{id:'a20_alms',deck:'adult',w:6,ch:20,a:[18,80],t:X('ใครมาขอข้าวที่ประตู','Who comes begging at the door'),
 xf:S=>X('เช้านี้มีนักบวชสามคนมายืนที่ประตูบ้าน คนหนึ่งถือบาตร ยืนเงียบไม่ขออะไร คนหนึ่งยื่นฝ่ามือมารับอาหาร'+(S.ya<=2140?' อีกคนเป็นผู้บูชาวาสุเทพ ร้องเพลงสรรเสริญ':' อีกคนเปลือยกาย ถือไม้เท้า')+' คุณมีข้าวพอให้คนเดียว','Three ascetics stand at your door this morning. One holds a bowl and waits in silence, asking for nothing. One holds out his palms to receive food. '+(S.ya<=2140?'The third is a devotee of Vasudeva, singing hymns.':'The third is naked and carries a staff.')+' You have rice enough for one.'),
 n:X('ชาวบ้านยุคนี้ให้อาหารนักบวชหลายสำนักเป็นเรื่องปกติ ภิกษุพุทธรับอาหารในบาตร นักบวชเชนบางกลุ่มรับด้วยฝ่ามือและกินยืน นักบวชอาชีวกถือไม้เท้าไผ่ ศิลาจารึกของพระเจ้าอโศกขอให้ให้ทานทั้งสมณะและพราหมณ์ ไม่ใช่เฉพาะสำนักเดียว','Lay people of this age commonly fed ascetics of many schools. Buddhist monks took food in a bowl; some Jain ascetics received it in their palms and ate standing; Ajivikas carried a bamboo staff. Ashoka’s edicts urge giving to both ascetics and Brahmins, not to one school alone.'),
 of:S=>[opt(X('ใส่ข้าวในบาตร','Put rice in the bowl'),S=>{fa20(S,'bud',1);fx({b:3,f:-1});return X('ภิกษุรับแล้วเดินต่อโดยไม่ขอบคุณ คุณรู้ภายหลังว่าการให้ต่างหากที่เป็นบุญของคุณ','The monk accepts and walks on without thanking you. Later you learn that the giving was your merit.')}),
    opt(X('วางข้าวบนฝ่ามือ','Put rice in the open palms'),S=>{fa20(S,'jain',1);fx({b:3,f:-1});return X('นักบวชกินตรงนั้นทันทีอย่างระมัดระวัง ไม่ให้เม็ดข้าวหล่นแม้เม็ดเดียว','The ascetic eats then and there, carefully, not dropping a single grain.')}),
    opt(X(S.ya<=2140?'ให้ผู้บูชาวาสุเทพ':'ให้นักบวชเปลือยที่ถือไม้เท้า',S.ya<=2140?'Give to the devotee of Vasudeva':'Give to the naked ascetic with the staff'),S=>{fa20(S,S.ya<=2140?'bhag':'aji',1);fx({b:3,f:-1});return X('เขาอวยพรคุณด้วยคำที่คุณไม่เคยได้ยิน แต่ฟังแล้วอบอุ่น','He blesses you with words you have never heard, but they feel warm.')})]},
{id:'a20_sacrifice',deck:'adult',w:5,ch:20,a:[18,70],cond:S=>S.ya>=2285,t:X('แพะสำหรับพิธี','A goat for the rite'),
 x:X('พราหมณ์ประจำหมู่บ้านบอกว่าปีนี้ต้องบูชายัญแพะหนึ่งตัว เพื่อให้ฝนตกและนาได้ผล แต่นักบวชที่ผ่านมาบอกว่าการฆ่าสัตว์ไม่ได้ทำให้ใครได้บุญ ให้ถวายข้าวกับนมแทน','The village Brahmin says a goat must be sacrificed this year so the rains come and the fields bear. But a passing ascetic says killing brings no one merit: offer rice and milk instead.'),
 n:X('ในกูฏทันตสูตร พระพุทธเจ้าเล่าถึงพิธีบูชายัญในอดีตที่ไม่มีการฆ่าสัตว์ ใช้เพียงเนย น้ำมัน นม และน้ำผึ้ง ✦ นักบวชเชนต่อต้านการฆ่าสัตว์เข้มงวดยิ่งกว่า ตลอดหลายร้อยปี พิธีบูชายัญด้วยสัตว์ค่อยๆ ลดลงในอินเดีย และการกินมังสวิรัติก็แพร่หลายขึ้น ซึ่งนักประวัติศาสตร์เห็นว่ามาจากอิทธิพลของหลายสำนักร่วมกัน','In the Kutadanta Sutta the Buddha tells of a great sacrifice of the past in which no animal was killed, only ghee, oil, milk and honey offered ✦. Jain ascetics opposed killing even more strictly. Over centuries animal sacrifice slowly declined in India and vegetarianism spread, which historians credit to many schools together.'),
 o:[opt(X('ถวายแพะตามพิธี','Give the goat for the rite'),S=>{fa20(S,'veda',1);fx({p:2,f:-2});return X('พิธีงดงาม ฝนตกตามฤดูปีนั้น ทุกคนบอกว่าเพราะแพะ','The rite is splendid and the rains come on time that year. Everyone credits the goat.')}),
    opt(X('ถวายข้าวกับนมแทน','Offer rice and milk instead'),S=>{fa20(S,'bud',.5);fa20(S,'jain',.5);fx({b:2,p:-1});return X('พราหมณ์ไม่พอใจ ฝนตกตามฤดูเหมือนกัน คุณไม่พูดอะไร แต่แพะของคุณยังมีชีวิต','The Brahmin is displeased. The rains come on time anyway. You say nothing, but your goat is still alive.')})]},
{id:'a20_vasala',deck:'youth',w:5,ch:20,a:[13,40],cond:S=>S.var20!=='cand',t:X('กินข้าวด้วยกันได้ไหม','May we eat together?'),
 x:X('เพื่อนที่คุณรู้จักตั้งแต่เด็กเป็นคนในตระกูลที่ทำงานเก็บขยะ ผู้ใหญ่บอกว่าไม่ควรกินข้าวร่วมกับเขา วันนี้เขาเอาขนมมาแบ่งให้คุณต่อหน้าคนอื่น','A friend you have known since childhood comes from a family that clears refuse. The grown-ups say you should not eat with him. Today he offers to share his sweets with you in front of everyone.'),
 n:X('วสลสูตรสอนว่า “คนไม่ได้เป็นคนถ่อยเพราะกำเนิด ไม่ได้เป็นพราหมณ์เพราะกำเนิด แต่เป็นเพราะการกระทำ” สงฆ์รับคนจากทุกวรรณะ เถรคาถามีบทกวีของภิกษุชื่อสุนีตะ ซึ่งเคยเป็นคนเก็บดอกไม้เหี่ยวทิ้ง ถึงอย่างนั้น การแบ่งแยกตามกำเนิดก็ยังคงอยู่และเข้มงวดขึ้นในหลายร้อยปีต่อมา','The Vasala Sutta teaches that “one is not an outcaste by birth, nor a Brahmin by birth, but by deeds”. The Sangha accepted people of every varna; the Theragatha has verses by a monk named Sunita who had swept up withered flowers for a living. Even so, division by birth persisted and grew stricter over the following centuries.'),
 o:[opt(X('นั่งกินด้วยกัน','Sit and eat with him'),S=>{fa20(S,'bud',.3);fx({so:3,b:3,p:-2});return X('ขนมหวานกว่าที่คิด ป้าข้างบ้านไม่ทักคุณไปหนึ่งเดือน','The sweets are sweeter than you expected. The neighbour aunt doesn’t speak to you for a month.')}),
    opt(X('ปฏิเสธอย่างสุภาพ','Politely refuse'),S=>{fx({p:1,b:-3,so:-1});return X('เขายิ้มเหมือนชินแล้ว คุณคิดถึงรอยยิ้มนั้นไปอีกนาน','He smiles as if he is used to it. You think about that smile for a long time.')})]},
{id:'a20_goforth',deck:'adult',w:3,ch:20,a:[16,55],cond:S=>!S.monk20,t:X('ออกบวช','Going forth'),
 x:X('คุณเห็นคนแก่ตาย เห็นเด็กป่วย และคิดว่าชีวิตในบ้านมีแต่ภาระ หลายคนในวัยของคุณโกนผม ห่มผ้าย้อมสี แล้วออกจากบ้านไปเป็นนักบวชพเนจร คุณจะไปกับใคร','You have seen the old die and children fall sick, and household life feels like nothing but burdens. Many of your age shave their heads, put on dyed cloth and leave home as wandering ascetics. Whom would you follow?'),
 n:X('การออกบวชเป็นทางเลือกที่พบบ่อยในยุคนี้ ทั้งชายและหญิง ตามพระวินัย ทาส ลูกหนี้ ทหารที่ยังรับราชการ และคนที่พ่อแม่ไม่อนุญาต บวชไม่ได้ เพื่อไม่ให้สงฆ์กลายเป็นที่หลบหนีภาระทางโลก นักบวชเชนเคร่งเรื่องการไม่ทำร้ายชีวิตที่สุด อาชีวกบางกลุ่มเปลือยกาย และทรมานตัวหนัก','Going forth was a common choice in this age, for men and women alike. Under the Vinaya, slaves, debtors, soldiers in service and those without their parents’ consent could not be ordained, so the Sangha would not become an escape from worldly duties. Jain ascetics were strictest about harming no life; some Ajivikas went naked and practised harsh austerities.'),
 of:S=>{const o=[];const nunOK=S.sex==='m'||S.ya<=2466;
  if(S.cls==='slave')return [opt(X('ขอให้นายปล่อยเป็นไทก่อน','Ask your master to free you first'),S=>{if(rnd()<.25){S.cls='dep';fx({b:8});return X('นายของคุณยอมปล่อย คุณเป็นไทแล้ว แต่ยังไม่แน่ใจว่าจะบวชไหม','Your master agrees. You are free, though no longer sure you want to renounce.')}fx({b:-4});return X('นายปฏิเสธ ทาสบวชไม่ได้','Your master refuses. A slave cannot be ordained.')}),opt(X('อยู่ต่อไป','Stay'),S=>{fx({b:-1});return X('คุณกลับไปทำงาน ความคิดนี้ยังวนอยู่ในใจ','You go back to work, the thought still circling.')})];
  if(nunOK&&budOK20(S))o.push(opt(X(S.sex==='f'?'บวชเป็นภิกษุณีในสงฆ์ของพระพุทธเจ้า':'บวชในสงฆ์ของพระพุทธเจ้า',S.sex==='f'?'Become a nun in the Buddha’s Sangha':'Join the Buddha’s Sangha'),S=>{ordain20(S,'bud');return X('ผมของคุณตกลงบนพื้น คุณรู้สึกเบาจนแปลกใจ','Your hair falls to the ground, and you feel surprisingly light.')}));
  o.push(opt(X('บวชเป็นนักบวชนิครนถ์','Become a Nigantha ascetic'),S=>{ordain20(S,'jain');return X('คุณได้ไม้กวาดอันเล็กไว้ปัดสัตว์เล็กออกจากทางเดิน','You are given a little broom to sweep small creatures from your path.')}));
  if(S.ya>=2200)o.push(opt(X('บวชเป็นนักบวชอาชีวก','Become an Ajivika ascetic'),S=>{ordain20(S,'aji');return X('ครูของคุณบอกว่าทางของคุณถูกกำหนดไว้แล้ว คุณแค่เดินตามไป','Your teacher says your path is already fixed; you need only walk it.')}));
  o.push(opt(X('อยู่ดูแลครอบครัวต่อไป','Stay and care for your family'),S=>{fx({so:2,b:1});return X('คุณใส่บาตรทุกเช้าแทน และพบว่านั่นก็เป็นทางหนึ่ง','Instead you give alms every morning, and find that is a path too.')}));return o.slice(0,3)}},
{id:'a20_recite',deck:'adult',w:6,ch:20,a:[18,70],cond:S=>!!S.monk20,t:X('กลุ่มท่องจำ','The reciters'),
 x:X('ภิกษุอาวุโสแบ่งนักบวชเป็นกลุ่ม แต่ละกลุ่มรับผิดชอบท่องจำคำสอนหมวดหนึ่งให้ครบ และสอนต่อให้รุ่นต่อไป คุณถูกชวนเข้ากลุ่ม','The senior monks divide the community into groups, each responsible for keeping one collection of teachings by heart and handing it on to the next generation. You are invited to join.'),
 n:X('คัมภีร์บาลีและอรรถกถากล่าวถึง “ภาณกะ” ผู้ทรงจำคำสอนแต่ละนิกาย เช่น ทีฆภาณกะ ผู้ทรงจำพระสูตรขนาดยาว คำสอนจำนวนมากมีโครงสร้างซ้ำๆ และเป็นรายการตัวเลข เช่น อริยสัจสี่ มรรคมีองค์แปด ซึ่งช่วยให้ท่องจำได้ วิธีนี้รักษาคำสอนไว้ได้หลายร้อยปีก่อนมีการเขียน','The Pali texts and commentaries mention bhanakas, reciters who each kept one collection, such as the Digha-bhanakas who held the long discourses. Many teachings are built of repetitions and numbered lists, the Four Noble Truths, the Eightfold Path, which made them easier to memorise. This kept the teachings for centuries before they were written down.'),
 o:[opt(X('เข้ากลุ่มท่องจำ','Join the reciters'),S=>{S.rec20=(S.rec20||0)+10;fx({kn:4,so:2});ms(X('เป็นผู้ทรงจำคำสอน','Became a reciter of the teachings'));return X('ทุกเย็นคุณท่องพร้อมกลุ่มจนเสียงกลายเป็นเสียงเดียว ถ้าใครพลาดคำหนึ่ง ทุกคนจะได้ยินทันที','Every evening you recite with the group until the voices become one. If anyone slips a word, everyone hears at once.')}),
    opt(X('ขอฝึกสมาธิแทน','Ask to practise meditation instead'),S=>{fx({b:4,kn:1});return X('คุณนั่งใต้ต้นไม้ทุกวันจนนกเลิกกลัว','You sit beneath a tree every day until the birds stop being afraid of you.')})]},
{id:'a20_stupa',deck:'adult',w:5,ch:20,a:[20,85],cond:S=>S.ya<=2280&&!S.don20&&['vid','var','pat','tax','anu','vil','kap','sav'].includes(S.rg),t:X('ชื่อบนราวสถูป','Your name on the stupa railing'),
 x:X('สถูปของเมืองกำลังขยาย ใครบริจาคพอสร้างเสาราวหรือคานหนึ่งชิ้น จะได้จารึกชื่อไว้บนหิน','The town’s stupa is being enlarged. Anyone who gives enough for one railing post or crossbar may have their name carved on the stone.'),
 n:X('ที่สถูปสาญจีและภารหุตมีจารึกผู้บริจาคหลายร้อยรายการ มีทั้งชาวบ้าน พ่อค้า กิลด์ช่าง และน่าแปลกใจว่ามีภิกษุและภิกษุณีจำนวนมาก แสดงว่านักบวชบางคนยังมีเงินของตัวเอง สถูปเป็นของชุมชน ไม่ใช่ของพระราชาคนเดียว','The stupas at Sanchi and Bharhut carry hundreds of donor inscriptions: villagers, merchants, craft guilds, and, surprisingly, many monks and nuns, showing that some renunciants still had money of their own. The stupas belonged to whole communities, not to kings alone.'),
 o:[opt(X('บริจาคและสลักชื่อ','Give, and have your name carved'),S=>{S.don20=1;S.ag=Math.max(0,S.ag-3);fa20(S,'bud',1);fx({b:5,p:2});ms(X('ชื่อถูกสลักบนราวสถูป','Name carved on a stupa railing'));return X('ช่างสลักชื่อคุณกับชื่อหมู่บ้าน ตัวอักษรเล็กนิดเดียว แต่หินจะอยู่นานกว่าคุณ','The carver cuts your name and your village’s. The letters are tiny, but the stone will outlast you.')}),
    opt(X('บริจาคโดยไม่ใส่ชื่อ','Give without a name'),S=>{S.ag=Math.max(0,S.ag-2);fa20(S,'bud',1);fx({b:4});return X('ไม่มีใครรู้ว่าเป็นของคุณ และคุณชอบแบบนั้น','No one knows it was yours, and you like it that way.')})]},
{id:'a20_brahmi',deck:'adult',w:5,ch:20,a:[12,50],cond:S=>S.ya<=2280&&S.lit<30,t:X('ตัวอักษรใหม่','The new letters'),
 x:X('เจ้าหน้าที่ที่อ่านศิลาจารึกของพระราชาสอนตัวอักษรให้ใครก็ได้ที่สนใจ ตัวอักษรเป็นขีดและวงกลมเรียบง่าย เขียนจากซ้ายไปขวา','The officer who reads the king’s edicts teaches the letters to anyone who wants to learn. They are simple strokes and circles, written left to right.'),
 n:X('อักษรพราหมีบนศิลาจารึกของพระเจ้าอโศกเป็นงานเขียนเก่าที่สุดในอินเดียที่ระบุอายุได้แน่นอน หลังยุคสินธุ จากพราหมีเกิดอักษรอีกมาก รวมทั้งอักษรปัลลวะในอินเดียใต้ ซึ่งเป็นต้นทางของอักษรขอมโบราณ และในที่สุดเป็นอักษรไทย คนไทยที่อ่านหนังสือนี้จึงใช้ลูกหลานของตัวอักษรเหล่านี้อยู่','The Brahmi letters of Ashoka’s edicts are the earliest securely dated writing in India after the Indus age. From Brahmi came many scripts, including the Pallava script of South India, which led to Old Khmer and at last to Thai. Anyone reading Thai today uses descendants of these letters.'),
 o:[opt(X('เรียนให้อ่านออก','Learn to read'),S=>{S.lit=clamp(S.lit+30,0,100);S.schOK=1;fx({kn:4});ms(X('อ่านอักษรพราหมีออก','Learned to read Brahmi'));return X('ชื่อของคุณเขียนได้ห้าตัว คุณเขียนบนพื้นดินจนลมพัดหายไป','Your name takes five letters. You write it in the dust until the wind blows it away.')}),
    opt(X('จำไว้ฟังอย่างเดียวพอ','Listening is enough for you'),S=>{fx({so:1});return X('คุณจำได้ทุกคำที่ได้ยิน ซึ่งก็เป็นวิธีที่คนทำกันมาเป็นพันปี','You remember every word you hear, as people have done for a thousand years.')})]},
{id:'a20_pilgrim',deck:'adult',w:4,ch:20,a:[25,70],cond:S=>S.ya<=2280&&(S.fa20&&S.fa20.bud>=1),t:X('จาริกสี่สถานที่','Pilgrimage to the four places'),
 x:X('คุณเก็บเงินพอจะเดินทางไปสี่สถานที่: ลุมพินีที่พระพุทธเจ้าประสูติ พุทธคยาที่ตรัสรู้ สารนาถที่แสดงธรรมครั้งแรก และกุสินาราที่ปรินิพพาน','You have saved enough to travel to the four places: Lumbini where the Buddha was born, Bodh Gaya where he awoke, Sarnath where he first taught, and Kusinara where he passed away.'),
 n:X('มหาปรินิพพานสูตรกล่าวถึงสี่สถานที่นี้ว่าเป็นที่ที่ผู้มีศรัทธาควรไปเห็น พระเจ้าอโศกเสด็จไปเองหลายแห่ง และตั้งเสาไว้ ทุกวันนี้คนไทยหลายหมื่นคนเดินทางไปสังเวชนียสถานเหล่านี้ทุกปี','The Mahaparinibbana Sutta names these four as places the faithful should go to see. Ashoka visited several himself and set up pillars. Today tens of thousands of Thais travel to these sites every year.'),
 o:[opt(X('ออกเดินทาง','Set out'),S=>{fa20(S,'bud',1);fx({tr:5,b:6,h:-3});S.ag=Math.max(0,S.ag-3);ms(X('จาริกสี่สถานที่','Made the pilgrimage to the four places'));return X('คุณเดินหลายเดือน รองเท้าขาดสองคู่ และกลับมาพร้อมใบโพธิ์แห้งหนึ่งใบ','You walk for months, wear out two pairs of sandals, and come home with one dry Bodhi leaf.')}),
    opt(X('เก็บเงินไว้ให้ครอบครัว','Keep the money for the family'),S=>{fx({f:2});return X('คุณบอกตัวเองว่าปีหน้าค่อยไป ปีหน้าก็มีเรื่องอื่นเสมอ','You tell yourself you will go next year. Next year there is always something else.')})]},
{id:'a20_dice',deck:'youth',w:4,ch:20,a:[15,45],t:X('ลูกเต๋าผลสมอ','Dice of vibhitaka nuts'),
 x:X('ผู้ชายในหมู่บ้านเล่นทอยลูกเต๋าที่ทำจากผลสมอพิเภก พนันกันด้วยเหรียญ บางคนเสียวัวไปแล้ว บางคนบอกว่าคืนนี้จะได้คืน','The village men play dice made of vibhitaka nuts, betting coins. Some have already lost a cow; some say they will win it back tonight.'),
 n:X('ฤคเวทมีบทเพลงของนักพนันที่เสียทุกอย่าง แม้แต่ภรรยา และคร่ำครวญว่าลูกเต๋าดึงดูดเขาเหมือนยาเสพติด ✦ ผลสมอพิเภกใช้เป็นลูกเต๋ามาตั้งแต่ยุคพระเวท และยังใช้เป็นยาในตำรับสมุนไพรทุกวันนี้','The Rigveda has the song of a gambler who has lost everything, even his wife, lamenting that the dice draw him like a drug ✦. Vibhitaka nuts were used as dice from Vedic times and are still used in herbal medicine today.'),
 o:[opt(X('ลองทอยสักครั้ง','Have one throw'),S=>{if(rnd()<.45){S.ag+=2;fx({b:3});return X('คุณได้สองเหรียญ และตัดสินใจเลิกขณะยังได้','You win two coins and decide to stop while ahead.')}S.ag=Math.max(0,S.ag-2);fx({b:-3});return X('คุณเสียสองเหรียญ และเข้าใจเพลงของนักพนันในฤคเวทขึ้นมาทันที','You lose two coins and suddenly understand the gambler’s song in the Rigveda.')}),
    opt(X('เดินผ่านไป','Walk on by'),S=>{fx({f:1});return X('คืนนั้นมีคนเสียวัวเพิ่มอีกตัว ไม่ใช่คุณ','That night someone else loses a cow. Not you.')})]},
{id:'a20_kisa',deck:'adult',w:8,ch:20,a:[18,60],cond:S=>S.ya<=2466&&S.kids.some(k=>k.dies!=null&&k.born+k.dies<=S.age),t:X('เมล็ดผักกาด','The mustard seed'),
 x:X('หลังคุณเสียลูกไป ภิกษุณีชราคนหนึ่งเล่าเรื่องหญิงชื่อกิสาโคตมี ที่อุ้มศพลูกไปขอยาทั่วเมือง พระพุทธเจ้าบอกให้หาเมล็ดผักกาดจากบ้านที่ไม่เคยมีใครตาย เธอเดินหาทั้งวัน แล้วเข้าใจว่าไม่มีบ้านแบบนั้นเลย','After you lose your child, an old nun tells you of a woman named Kisa Gotami who carried her dead baby through the town begging for medicine. The Buddha told her to bring a mustard seed from a house where no one had ever died. She searched all day, and understood there was no such house.'),
 n:X('เรื่องกิสาโคตมีมาจากอรรถกถา ✦ ส่วนบทกวีของเธอเองอยู่ในเถรีคาถา ในยุคนี้เด็กเกือบครึ่งหนึ่งไม่รอดถึงวัยผู้ใหญ่ เกือบทุกครอบครัวเคยเสียลูก เรื่องนี้ยังถูกเล่าในวัดไทยเพื่อปลอบคนที่สูญเสีย','The story of Kisa Gotami comes from the commentaries ✦; verses attributed to her are in the Therigatha. In this age nearly half of all children did not live to grow up, and almost every family had lost a child. The story is still told in Thai temples to comfort the bereaved.'),
 o:[opt(X('ฟังจนจบ','Listen to the end'),S=>{fx({b:4,so:2});return X('ความเศร้ายังอยู่ แต่คุณรู้ว่าไม่ได้อยู่คนเดียวกับมัน','The grief stays, but you know you are not alone with it.')}),
    opt(X('ไปนั่งกับแม่ที่เพิ่งเสียลูกอีกคน','Go and sit with another mother who has just lost a child'),S=>{fx({so:4,b:3});return X('คุณไม่พูดอะไร แค่นั่งด้วย และนั่นก็พอ','You say nothing, only sit with her, and that is enough.')})]},
{id:'a20_greek',deck:'adult',w:5,ch:20,a:[16,70],cond:S=>['tax','vid'].includes(S.rg)&&S.ya<=2190,t:X('เพื่อนบ้านชาวยวนะ','Yavana neighbours'),
 x:X('ครอบครัวกรีกที่อยู่ติดกันเรียกชื่อเทพของพวกเขาเป็นภาษาแปลก แต่ลูกชายของพวกเขาก็ใส่บาตรทุกเช้า และลูกสาวแต่งงานกับเพื่อนของคุณ เหรียญในตลาดมีอักษรสองแบบ ด้านหนึ่งกรีก อีกด้านขโรษฐี','The Greek family next door call their gods by strange names, yet their son gives alms every morning and their daughter has married your friend. Coins in the market carry two scripts: Greek on one side, Kharosthi on the other.'),
 n:X('กษัตริย์กรีกในแคว้นคันธาระทำเหรียญสองภาษา มีจารึกหลายชิ้นที่ชาวกรีกบริจาคให้สถูปพุทธ และช่างในคันธาระผสมแบบศิลปะกรีกกับเรื่องพุทธจนเกิดศิลปะคันธาระ ซึ่งมีส่วนสร้างรูปพระพุทธเจ้ายุคแรก','Greek kings of Gandhara struck bilingual coins; several inscriptions record Greeks giving to Buddhist stupas; and Gandharan craftsmen blended Greek art with Buddhist stories into Gandharan art, which helped shape the earliest images of the Buddha.'),
 o:[opt(X('ชวนพวกเขากินข้าว','Invite them to eat'),S=>{fx({so:3,tr:2,b:2});return X('พวกเขาเอาไวน์มาด้วย คุณเอาข้าวกับแกงถั่ว ทุกคนกินอิ่ม','They bring wine; you bring rice and dal. Everyone eats their fill.')}),
    opt(X('ให้พวกเขาสอนตัวอักษรกรีก','Ask them to teach you Greek letters'),S=>{S.lit=clamp(S.lit+10,0,100);fx({kn:3});return X('อักษรกรีกเขียนจากซ้ายไปขวา เหมือนพราหมี แต่หน้าตาไม่เหมือนกันเลย','Greek runs left to right, like Brahmi, but looks nothing like it.')})]},
{id:'e20_tell',deck:'elder',w:8,ch:20,a:[45,90],cond:S=>S.ya<=2427&&S.fa20&&(S.fa20.bud||0)>=1,t:X('เล่าเรื่องพระพุทธเจ้าให้เด็กๆ ฟัง','Telling the young about the Buddha'),
 xf:S=>X('เด็กๆ ในหมู่บ้านล้อมคุณ ขอให้เล่าเรื่องพระพุทธเจ้า เรื่องที่คุณได้ยินมามีไม่มาก: '+(S.ya>2292?'นักบวชผู้ออกจากบ้าน ทรมานตัวจนเกือบตาย แล้วพบทางสายกลาง ตรัสรู้ใต้ต้นไม้ และสอนอยู่สี่สิบกว่าปี':'เรื่องที่เล่าต่อกันมาหลายชั่วคน ซึ่งเริ่มมีปาฏิหาริย์มากขึ้นทุกรุ่น')+' เด็กๆ อยากฟังเรื่องที่ตื่นเต้นกว่านั้น','The village young ones crowd round and ask for the story of the Buddha. You have not heard much: '+(S.ya>2292?'an ascetic who left home, nearly starved himself to death, found the middle way, awoke under a tree and taught for over forty years.':'a story passed down for generations, gaining wonders with every telling.')+' The young want something more exciting.'),
 n:X('พระสูตรชั้นต้นเล่าเรื่องวัยเด็กและชีวิตก่อนออกบวชของพระพุทธเจ้าไว้น้อยมาก พุทธประวัติต่อเนื่องครบเรื่อง ทั้งวังสามฤดู การเห็นเทวทูตสี่ และปาฏิหาริย์มากมาย มาประกอบเป็นเรื่องเดียวในงานที่เขียนภายหลังหลายร้อยปี เช่นพุทธจริต (ศตวรรษที่ 1–2) และนิทานกถา (ราวศตวรรษที่ 5) เรื่องเล่าย่อมเติบโตเมื่อถูกเล่าด้วยความรัก สำหรับชาวพุทธ สิ่งสำคัญที่สุดคือคำสอน มากกว่ารายละเอียดของเรื่อง','The early discourses say very little about the Buddha’s childhood and life before he left home. The full continuous story, with its palaces for three seasons, the four sights and many wonders, came together in works written centuries later, such as the Buddhacarita (1st–2nd century CE) and the Nidanakatha (around the 5th century). Stories grow when they are told with love; for Buddhists, the teaching matters more than the details.'),
 o:[opt(X('เล่าตามที่ได้ยินมาเป๊ะๆ','Tell it exactly as you heard it'),S=>{S.tell20='plain';fx({kn:2,so:1});return X('เด็กบางคนหลับ แต่คนหนึ่งถามคำถามที่ดีมากจนคุณตอบไม่ได้','Some of the children doze off, but one asks a question so good you cannot answer it.')}),
    opt(X('เติมปาฏิหาริย์ให้ตื่นเต้นขึ้น','Add a wonder or two to liven it up'),S=>{S.tell20='wonder';fx({so:3,b:3});return X('คุณเล่าว่ามีดอกบัวผุดขึ้นรองทุกก้าวที่พระองค์เดินตอนเพิ่งประสูติ เด็กๆ ตาโต และในเกมนี้ พวกเขาจะเล่าต่อให้ลูกหลานแบบที่ใหญ่กว่าเดิม','You tell how lotuses sprang up under each step he took as a newborn. The children’s eyes go wide, and in this game they will pass it on bigger still.')}),
    opt(X('ไม่เล่าเรื่องชีวิต แต่เล่าคำสอน','Skip the life; tell the teaching'),S=>{S.tell20='teach';fa20(S,'bud',.5);fx({kn:3});return X('คุณสอนว่าทุกอย่างไม่เที่ยง เด็กคนหนึ่งร้องไห้เพราะนึกถึงหมาที่ตายไป คุณกอดเขา','You teach that everything changes. One child cries, remembering a dog that died. You hold him.')})]}
];
function ordain20(S,k){S.monk20=k;S.partner=0;S.car='samana';S.clv=Math.max(1,S.clv||0);S.cxp=0;S.focus='job';fa20(S,k,2);fx({b:5,so:-1});
  ms(X('ออกบวชเป็น'+MONK20[k][S.sex==='f'?'f':'m'].th,'Went forth as '+MONK20[k][S.sex==='f'?'f':'m'].en))}

const DEC_CAR20=[
{id:'k20_order',a:[12,45],w:20,ch:20,cond:S=>S.car==='samana'&&!S.monk20,t:X('จะบวชกับสำนักไหน','Which order to join'),
 x:X('คุณเลือกชีวิตนักบวชแล้ว แต่ยังต้องเลือกครู ภิกษุของพระโคตมะ นักบวชนิครนถ์ของมหาวีระ และนักบวชอาชีวก ต่างก็ยินดีรับคุณ','You have chosen the renunciant’s life, but must still choose a teacher. The monks of Gotama, the Nigantha ascetics of Mahavira and the Ajivikas would all welcome you.'),
 n:X('ในยุคนี้ทั้งสามสำนักมีนักบวชชายและหญิง และแข่งกันหาผู้อุปถัมภ์ ทั้งสามสำนักได้รับราชูปถัมภ์ในบางช่วง แต่มีเพียงสองสำนักที่ยังอยู่ถึงทุกวันนี้','In this age all three orders had male and female ascetics and competed for supporters. All three won royal favour at times; only two survive today.'),
 of:S=>{const o=[];if(budOK20(S)&&(S.sex==='m'||S.ya<=2466))o.push(opt(X('สงฆ์ของพระพุทธเจ้า','The Buddha’s Sangha'),S=>{ordain20(S,'bud');return X('คุณเรียนวิธีถือบาตรให้มั่น และเดินให้ช้า','You learn to hold the bowl steady, and to walk slowly.')}));
  o.push(opt(X('นักบวชนิครนถ์','The Niganthas'),S=>{ordain20(S,'jain');return X('ครูสอนให้คุณกรองน้ำ ปัดทางเดิน และไม่กินหลังพระอาทิตย์ตก','Your teacher shows you how to strain water, sweep your path and never eat after sunset.')}));
  if(S.ya>=2200)o.push(opt(X('นักบวชอาชีวก','The Ajivikas'),S=>{ordain20(S,'aji');return X('ครูบอกว่าวิญญาณทุกดวงจะหลุดพ้นเมื่อถึงเวลาที่กำหนดไว้ ไม่เร็วกว่าหรือช้ากว่านั้น','Your teacher says every soul will be freed at its appointed time, not a moment sooner or later.')}));return o}},
{id:'k20_alms',a:[14,85],w:6,ch:20,cond:S=>!!S.monk20,t:X('บิณฑบาต','The alms round'),
 x:X('เช้ามืด คุณถือบาตรเดินเข้าหมู่บ้านอย่างเงียบๆ ไม่ขอ ไม่เลือกบ้าน รับทุกอย่างที่คนใส่ให้ วันนี้หญิงยากจนคนหนึ่งใส่ข้าวบูดลงในบาตรของคุณ','At first light you walk into the village with your bowl, in silence, asking nothing, choosing no house, taking whatever is given. Today a poor woman puts stale rice in your bowl.'),
 n:X('ภิกษุในยุคนี้บิณฑบาตทุกวันและฉันสิ่งที่ได้รับ รวมทั้งเนื้อ ถ้าไม่ได้ฆ่าเพื่อตน ส่วนนักบวชเชนเคร่งกว่ามาก รับเฉพาะอาหารที่ไม่ได้ทำเพื่อตนโดยเฉพาะ การตักบาตรที่คนไทยทำทุกเช้าสืบมาจากธรรมเนียมนี้โดยตรง','Monks of this age begged daily and ate what they received, even meat if it had not been killed for them. Jain ascetics were far stricter, taking only food not prepared specially for them. The morning almsgiving Thais still practise comes straight from this custom.'),
 o:[opt(X('ฉันด้วยความยินดี','Eat it gladly'),S=>{fx({b:3,h:-1});return X('ข้าวบูดไม่อร่อย แต่ความตั้งใจของเธออร่อย','The stale rice is not good, but her intention is.')}),
    opt(X('ให้ข้าวต่อแก่ขอทานข้างทาง','Pass the rice on to a beggar by the road'),S=>{fx({so:3,b:2});return X('ขอทานกินหมดในพริบตา คุณอดอาหารวันนั้น และรู้สึกอิ่มอย่างประหลาด','The beggar eats it in a blink. You go hungry that day and feel strangely full.')})]},
{id:'k20_pot',a:[16,70],w:6,ch:20,cond:S=>S.car==='potter',t:X('ภาชนะดำเงา','The black polished ware'),
 x:X('ช่างอาวุโสสอนวิธีทำภาชนะผิวดำเงาเหมือนกระจก ซึ่งคนรวยในเมืองยอมจ่ายแพง แต่ไม่บอกเคล็ดลับสุดท้ายว่าเผาอย่างไรให้เงาแบบนั้น','A master potter teaches you to make ware with a black, mirror-like gloss that rich townsfolk pay dearly for, but keeps back the last secret of how to fire it to that shine.'),
 n:X('ภาชนะดินเผาสีดำขัดเงาภาคเหนือ เป็นเครื่องปั้นชั้นดีของลุ่มแม่น้ำคงคาในยุคนี้ พบตามเมืองต่างๆ ตั้งแต่ตักกสิลาถึงกลิงคะ นักโบราณคดียังถกเถียงกันว่าทำผิวเงาแบบนั้นได้อย่างไร','Northern Black Polished Ware was the fine pottery of the Ganges valley in this age, found in towns from Taxila to Kalinga. Archaeologists still argue over how its gloss was made.'),
 o:[opt(X('ทดลองเองจนสำเร็จ','Experiment until you crack it'),S=>{fx({cr:5});addItem('pot20');addItem('pot20');return X('หลังเผาเสียไปสามสิบใบ ใบที่สามสิบเอ็ดเงาจนคุณเห็นหน้าตัวเอง','After thirty spoiled pots, the thirty-first shines so you can see your face in it.')}),
    opt(X('ทำหม้อธรรมดาขายคนทั่วไป','Make plain pots for ordinary people'),S=>{fx({cr:2,so:2});addItem('pot20');return X('หม้อของคุณไม่เงา แต่ทุกบ้านในหมู่บ้านมีสักใบ','Your pots don’t shine, but every house in the village owns one.')})]},
{id:'k20_trade',a:[16,70],w:6,ch:20,cond:S=>S.car==='trader',t:X('ป่าที่มียักษ์','The forest of yakkhas'),
 x:X('กองเกวียนของคุณต้องผ่านป่าใหญ่ คนนำทางเล่าว่าในป่ามียักษ์หลอกให้คนเทน้ำทิ้ง แล้วกินคนทั้งกองคาราวาน คนในกองเริ่มกลัว','Your caravan must cross a great forest. The guide says yakkhas there trick travellers into pouring away their water, then eat the whole caravan. Your people grow afraid.'),
 n:X('ชาดกหลายเรื่องเล่าถึงกองคาราวานห้าร้อยเล่มเกวียนที่ต้องข้ามป่าและทะเลทราย ✦ พ่อค้าเป็นผู้อุปถัมภ์สำคัญของศาสนาพุทธและเชน และนักบวชมักเดินทางไปกับกองคาราวาน ศาสนาจึงเดินทางไปตามเส้นทางการค้า','Many Jatakas tell of caravans of five hundred carts crossing forests and deserts ✦. Merchants were key supporters of Buddhism and Jainism, and ascetics often travelled with caravans, so the faiths spread along the trade routes.'),
 o:[opt(X('เก็บน้ำไว้ไม่ว่าใครจะพูดอะไร','Keep the water, whatever anyone says'),S=>{S.ag+=3;fx({p:3,tr:3});return X('กลางป่ามีคนแปลกหน้าบอกว่าข้างหน้ามีบึงน้ำ ให้เทน้ำทิ้งให้เกวียนเบา คุณไม่เชื่อ และทุกคนรอด','Mid-forest, strangers say there is a lake ahead; pour out your water to lighten the carts. You don’t believe them, and everyone survives.')}),
    opt(X('ชวนนักบวชร่วมเดินทางด้วย','Invite some ascetics to travel with you'),S=>{fa20(S,'bud',.5);S.ag+=2;fx({so:3,b:2});return X('ทุกคืนนักบวชสวดมนต์ คนในกองหายกลัว และคุณได้ฟังธรรมฟรีตลอดทาง','The ascetics chant every night, your people lose their fear, and you hear teachings all the way for free.')})]},
{id:'k20_priest',a:[18,75],w:6,ch:20,cond:S=>S.car==='priest',t:X('ค่าทักษิณา','The priest’s fee'),
 x:X('เศรษฐีคนหนึ่งจ้างคุณประกอบพิธีบูชาไฟใหญ่ถึงสิบสองวัน ค่าทักษิณาเป็นวัวร้อยตัว แต่คืนก่อนพิธี ลูกชายของเศรษฐีบอกว่าเขาไปฟังนักบวชพุทธมา และคิดว่าพิธีนี้ไม่จำเป็น','A rich merchant hires you for a great twelve-day fire rite, the fee a hundred cows. But the night before, his son says he has been listening to Buddhist monks and thinks the rite is pointless.'),
 n:X('พราหมณ์ได้ค่าตอบแทนเรียกว่า “ทักษิณา” ซึ่งอาจเป็นวัว ทอง หรือที่ดิน คัมภีร์พุทธวิจารณ์พิธีบูชายัญที่ฟุ่มเฟือย แต่ก็เรียกคนดีว่า “พราหมณ์ที่แท้” และพราหมณ์หลายคนเป็นศิษย์คนสำคัญของพระพุทธเจ้า ความสัมพันธ์จึงซับซ้อนกว่าการเป็นศัตรูกัน','Brahmins were paid a fee called dakshina: cows, gold or land. Buddhist texts criticised lavish sacrifices, yet called a good person “a true Brahmin”, and many Brahmins were among the Buddha’s leading disciples. The relationship was more complicated than simple enmity.'),
 o:[opt(X('ทำพิธีให้งดงามที่สุด','Perform the rite as splendidly as you can'),S=>{S.ag+=6;fa20(S,'veda',1);fx({p:4,kn:2});return X('ไฟลุกสวยงามสิบสองวัน ลูกชายเศรษฐียืนดูอยู่ข้างหลัง และไม่ได้พูดอะไรอีก','The fires burn beautifully for twelve days. The merchant’s son watches from the back and says nothing more.')}),
    opt(X('คุยกับลูกชายเศรษฐีก่อน','Talk with the merchant’s son first'),S=>{fx({kn:4,so:2});return X('คุณสองคนเถียงกันถึงเช้า แล้วตกลงกันได้เรื่องเดียว: ความดีสำคัญกว่าพิธี','You argue until dawn and agree on one thing: goodness matters more than rites.')})]},
{id:'k20_mahout',a:[18,60],w:7,ch:20,cond:S=>S.car==='mahout',t:X('ช้างเก้าพันเชือก','Nine thousand elephants'),
 x:X('กองทัพหลวงมีช้างมากจนนับไม่ถ้วน คุณได้รับช้างพลายหนุ่มที่ไม่ยอมให้ใครขี่ ต้องใช้เวลาหลายเดือนกว่าจะเชื่อใจกัน','The royal army has more elephants than anyone can count. You are given a young bull that will let no one ride him; it will take months to win each other’s trust.'),
 n:X('พลินีผู้ลุง นักเขียนโรมัน บันทึกจากรายงานของชาวกรีกว่ากษัตริย์แห่งปาฏลีบุตรมีช้าง 9,000 เชือก เมื่อจันทรคุปต์ยกดินแดนให้ซีลูคัสแลกเปลี่ยน ซีลูคัสได้ช้าง 500 เชือก ซึ่งต่อมาช่วยให้ชนะสงครามใหญ่ในตะวันตก','The Roman writer Pliny the Elder, drawing on Greek reports, recorded that the king of Pataliputra had 9,000 elephants. When Chandragupta made peace with Seleucus, Seleucus received 500 elephants, which later helped him win a great battle in the west.'),
 o:[opt(X('นอนข้างช้างทุกคืน','Sleep beside the elephant every night'),S=>{fx({sv:3,so:2});return X('สามเดือนต่อมา ช้างใช้งวงยกคุณขึ้นหลังเอง','Three months later the elephant lifts you onto its back with its own trunk.')}),
    opt(X('ใช้ขอสับให้เชื่อฟัง','Use the hook to make it obey'),S=>{fx({sv:2,b:-2});if(rnd()<.2){fx({h:-12});return X('ช้างเหวี่ยงคุณกระเด็น ซี่โครงหักสองซี่ และมันไม่เคยไว้ใจคุณอีกเลย','The elephant flings you off; two ribs crack, and it never trusts you again.')}return X('ช้างเชื่อฟัง แต่มองคุณด้วยตาที่ทำให้คุณนอนไม่หลับ','The elephant obeys, but looks at you with eyes that keep you awake at night.')})]},
{id:'k20_physician',a:[18,75],w:6,ch:20,cond:S=>S.car==='physician',t:X('ยาจากทุกต้นไม้','Medicine in every plant'),
 x:X('คนไข้ของคุณมีทั้งเศรษฐี ภิกษุ และขอทาน หมอรุ่นพี่บอกว่าอย่ารักษาฟรี เพราะคนจะไม่เชื่อยา แต่ภิกษุไม่มีเงิน','Your patients are merchants, monks and beggars. An older physician says never treat for free, or people won’t trust the medicine. But monks have no money.'),
 n:X('พระวินัยมีบทว่าด้วยยา ระบุยาที่ภิกษุใช้ได้ เช่นเนยใส น้ำมัน น้ำผึ้ง น้ำอ้อย และรากไม้ต่างๆ ตำราแพทย์อายุรเวทอย่างจรกสังหิตาเรียบเรียงในยุคหลังจากนี้ แต่ใช้ความรู้ที่สั่งสมมาหลายร้อยปี','The Vinaya has a chapter on medicines, listing what monks might use: ghee, oil, honey, molasses and various roots. Ayurvedic texts such as the Charaka Samhita were compiled later, but drew on centuries of gathered knowledge.'),
 o:[opt(X('รักษาภิกษุฟรี','Treat the monks for free'),S=>{fa20(S,'bud',.5);fx({kn:3,so:3});return X('ภิกษุไม่มีเงิน แต่บอกต่อจนเศรษฐีทั้งเมืองมาหาคุณ','The monks have no money, but they spread the word until every merchant in town comes to you.')}),
    opt(X('เก็บเงินทุกคน เท่ากัน','Charge everyone the same'),S=>{S.ag+=3;fx({kn:2});return X('คุณร่ำรวยขึ้น และขอทานหาหมอคนอื่น','You grow richer, and the beggars find another physician.')})]},
{id:'k20_carve',a:[16,70],w:6,ch:20,cond:S=>S.car==='carver',t:X('ยักษิณีบนเสา','The yakkhini on the post'),
 xf:S=>S.ya<=2280?X('คุณได้รับมอบให้แกะยักษิณีโหนกิ่งไม้บนเสาประตูสถูป หัวหน้าช่างบอกว่าต้องสวยจนคนเดินผ่านหยุดมอง แต่ต้องดูเป็นผู้พิทักษ์ ไม่ใช่นางรำ','You are given a yakkhini to carve, hanging from a branch on a stupa gateway post. The master says she must be lovely enough to stop passers-by, yet look like a guardian, not a dancer.'):X('คุณแกะงาช้างเป็นหวีและกล่องให้คนรวยในเมือง หัวหน้าช่างบอกว่าวันหนึ่งพระราชาจะสร้างอนุสาวรีย์หิน และต้องการช่างที่มือนิ่งพอ','You carve ivory into combs and boxes for the town’s rich. The master says one day the king will build in stone, and will want carvers with steady hands.'),
 n:X('ยักษิณีบนประตูสาญจีเป็นภาพของเทพีแห่งความอุดมสมบูรณ์ที่ชาวบ้านบูชามาก่อน ช่างงาช้างและช่างไม้ย้ายมาแกะหินในยุคนี้ จึงใช้เทคนิคแกะไม้แกะงากับหิน เสาหินของพระเจ้าอโศกขัดเงาจนหลายคนเคยเข้าใจผิดว่าเป็นโลหะ','The yakkhinis of the Sanchi gates are fertility goddesses villagers already worshipped. Ivory carvers and woodworkers turned to stone in this age, bringing their techniques with them. Ashoka’s pillars were polished so finely that some people once took them for metal.'),
 o:[opt(X('แกะอย่างตั้งใจที่สุด','Carve with all your care'),S=>{fx({cr:5,p:2});return X('สองพันปีต่อมา ในเกมนี้ นักท่องเที่ยวถ่ายรูปงานของคุณมากที่สุดบนประตูนั้น','Two thousand years later, in this game, your work is the most photographed on that gate.')}),
    opt(X('ขอแกะเรื่องชาดกแทน','Ask to carve a Jataka scene instead'),S=>{fa20(S,'bud',.5);fx({cr:3,kn:2});return X('คุณแกะลิงที่ใช้ตัวเองเป็นสะพานให้ฝูงหนีข้ามแม่น้ำ คนดูยิ้มทุกคน','You carve the monkey king who made himself a bridge for his troop to escape across the river. Everyone who sees it smiles.')})]}
];

/* ---------- legend mode: tales of the age ---------- */
const LEG20=[
{id:'l20_angu',deck:'adult',w:8,ch:20,lg:1,a:[15,70],cond:S=>S.rg==='sav'&&S.ya<=2473&&S.ya>=2430,t:X('โจรที่ร้อยนิ้วเป็นมาลัย','The bandit with a garland of fingers'),
 x:X('ทั้งสาวัตถีกลัวโจรชื่อองคุลิมาล ที่ฆ่าคนแล้วตัดนิ้วร้อยเป็นมาลัยคล้องคอ วันหนึ่งมีข่าวว่าเขาวิ่งไล่นักบวชคนหนึ่ง แต่วิ่งเท่าไรก็ตามไม่ทัน ทั้งที่นักบวชเดินช้าๆ','All Savatthi fears a bandit called Angulimala, who kills people and strings their fingers into a garland. One day word comes that he chased an ascetic but, however fast he ran, could not catch him, though the ascetic only walked.'),
 n:X('ในองคุลิมาลสูตร นักบวชคนนั้นคือพระพุทธเจ้า ผู้พูดว่า “เราหยุดแล้ว ท่านต่างหากที่ยังไม่หยุด” องคุลิมาลจึงทิ้งดาบและบวช ✦ คนไทยรู้จักบท “องคุลิมาลปริตร” ที่สวดให้หญิงคลอดบุตรปลอดภัย','In the Angulimala Sutta the ascetic is the Buddha, who says, “I have stopped; it is you who have not stopped,” and Angulimala throws down his sword and becomes a monk ✦. Thais know the Angulimala paritta, chanted for women in childbirth.'),
 o:[opt(X('ไม่เชื่อว่าโจรจะกลับใจได้','Doubt a bandit can change'),S=>{fx({kn:1});return X('หลายเดือนต่อมา คุณใส่บาตรภิกษุผอมๆ คนหนึ่ง แล้วมีคนกระซิบว่านั่นคือเขา มือคุณสั่น','Months later you give alms to a thin monk, and someone whispers that it is him. Your hands shake.')}),
    opt(X('เชื่อว่าใครก็เปลี่ยนได้','Believe anyone can change'),S=>{fa20(S,'bud',.5);fx({b:4,so:2});return X('คุณเลิกพูดถึงคนที่เคยทำผิดต่อคุณ แล้วรู้สึกเบาขึ้น','You stop talking about the people who once wronged you, and feel lighter.')})]},
{id:'l20_muca',deck:'adult',w:6,ch:20,lg:1,a:[10,80],cond:S=>S.ya<=2473,t:X('พญานาคกับพายุเจ็ดวัน','The naga king and the seven-day storm'),
 x:X('ชาวบ้านเล่าว่า หลังตรัสรู้ไม่นาน พายุฝนตกเจ็ดวันเจ็ดคืน พญานาคชื่อมุจลินท์ออกมาจากสระ ขดตัวรอบพระพุทธเจ้าเจ็ดรอบ และแผ่พังพานบังฝนให้','People tell that soon after the awakening, a storm raged seven days and nights, and a naga king named Mucalinda came out of a pond, coiled seven times around the Buddha and spread his hood over him against the rain.'),
 n:X('เรื่องนี้อยู่ในอุทาน ✦ รูปพระปางนาคปรกที่คนไทยเกิดวันเสาร์บูชา มาจากเรื่องนี้ นาคเป็นเทพของน้ำที่ชาวบ้านบูชามาก่อน เรื่องนี้แสดงว่าศาสนาพุทธรับความเชื่อท้องถิ่นเข้ามาให้เป็นผู้ปกป้อง แทนที่จะปฏิเสธ','This is told in the Udana ✦. The Buddha sheltered by the naga, the image for Thais born on Saturday, comes from this story. Nagas were water gods villagers already worshipped; the story shows Buddhism taking local beliefs in as protectors instead of rejecting them.'),
 o:[opt(X('ไปวางนมที่สระ','Leave milk at the pond'),S=>{fa20(S,'yak',.5);fa20(S,'bud',.5);fx({b:3});return X('คุณไม่รู้ว่าตัวเองกำลังบูชาใคร นาคหรือพระพุทธเจ้า หรือทั้งสอง','You are not sure whom you are honouring, the naga or the Buddha, or both.')}),
    opt(X('เล่าต่อให้เด็กๆ','Pass the tale on to the children'),S=>{fx({so:2,b:2});return X('ในเรื่องเล่าของเด็กๆ พายุยาวขึ้นเป็นสิบวัน และนาคมีเจ็ดหัว','In the children’s version the storm lasts ten days and the naga has seven heads.')})]},
{id:'l20_hariti',deck:'adult',w:6,ch:20,lg:1,a:[18,70],cond:S=>S.ya<=2200,t:X('ยักษิณีผู้กินเด็ก','The yakkhini who ate children'),
 x:X('แม่ๆ ในหมู่บ้านเล่าเรื่องยักษิณีหาริตี ที่ลักเด็กของคนอื่นไปกิน จนพระพุทธเจ้าซ่อนลูกคนเล็กของนางไว้ นางจึงรู้ว่าแม่คนอื่นเจ็บปวดแค่ไหน แล้วกลายเป็นผู้คุ้มครองเด็กแทน','The village mothers tell of Hariti, a yakkhini who stole other people’s children to eat, until the Buddha hid her own youngest child. Then she understood other mothers’ pain and became a protector of children instead.'),
 n:X('เรื่องหาริตีอยู่ในคัมภีร์พุทธยุคหลัง ✦ รูปปั้นหาริตีอุ้มลูกพบมากในแคว้นคันธาระ และนางกลายเป็นเทพีคุ้มครองเด็กไปไกลถึงจีนและญี่ปุ่น ตัวอย่างของเทพท้องถิ่นที่ถูกรับเข้ามาในศาสนาพุทธ','Hariti’s story is in later Buddhist texts ✦. Statues of Hariti holding children are common in Gandhara, and she became a protector of children as far as China and Japan: another local goddess taken into Buddhism.'),
 o:[opt(X('ทำบุญให้หาริตีคุ้มครองลูก','Make an offering for Hariti to protect the children'),S=>{fa20(S,'yak',1);fx({b:3});return X('คุณวางข้าวไว้ที่ประตู ใครจะกินก็ตาม ลูกๆ ของคุณหลับสบาย','You leave rice at the door. Whoever eats it, your children sleep soundly.')}),
    opt(X('คิดถึงแม่คนอื่นๆ','Think of the other mothers'),S=>{fx({so:3});return X('คุณส่งอาหารไปให้บ้านที่เพิ่งมีลูกอ่อน','You send food to the house with a newborn.')})]},
{id:'l20_vessantara',deck:'adult',w:6,ch:20,lg:1,a:[14,80],t:X('เจ้าชายที่ให้ทุกอย่าง','The prince who gave everything away'),
 x:X('นักเล่าเรื่องในตลาดเล่าเรื่องเจ้าชายเวสสันดร ผู้ให้ช้างเผือกของบ้านเมือง ให้รถ ให้ลูก และให้แม้แต่ภรรยาของตน คนฟังร้องไห้ เถียงกัน และกลับมาฟังซ้ำทุกปี','A storyteller in the market tells of Prince Vessantara, who gave away the kingdom’s white elephant, his chariot, his children and even his wife. The listeners weep, argue, and come back to hear it again every year.'),
 n:X('เวสสันดรชาดกเป็นชาติสุดท้ายก่อนเป็นพระพุทธเจ้า ✦ ถูกแกะไว้บนประตูสาญจีตั้งแต่สองพันปีก่อน คนไทยฟังในงานเทศน์มหาชาติ และคนก็ยังเถียงกันจนวันนี้ว่าการให้ลูกและภรรยาเป็นความดีหรือไม่','The Vessantara Jataka tells the last life before the Buddha ✦. It was carved on the Sanchi gates two thousand years ago; Thais hear it at the Thet Mahachat sermon, and people still argue today over whether giving away a wife and children can be good.'),
 o:[opt(X('ร้องไห้ตอนเด็กๆ ถูกพาไป','Weep when the children are led away'),S=>{fx({b:2,so:2});return X('คนทั้งตลาดร้องไห้กับคุณ นักเล่าเรื่องได้เหรียญมากที่สุดในปีนั้น','The whole market weeps with you, and the storyteller earns more coins than all year.')}),
    opt(X('เถียงว่าเจ้าชายทำผิด','Argue that the prince was wrong'),S=>{fx({kn:2,so:-1});return X('ป้าคนหนึ่งเห็นด้วยกับคุณ ลุงคนหนึ่งไม่เห็นด้วย ทั้งสองยังเถียงกันหลังคุณกลับบ้าน','An aunt agrees with you, an uncle doesn’t, and they are still arguing after you go home.')})]},
{id:'l20_84000',deck:'adult',w:6,ch:20,lg:1,a:[14,80],cond:S=>S.ya<=2285&&S.ya>=2220,t:X('สถูปแปดหมื่นสี่พันองค์','Eighty-four thousand stupas'),
 x:X('คนเล่าว่าพระเจ้าอโศกเปิดสถูปเก่าแปดองค์ เอาพระธาตุออกมาแบ่งเป็นแปดหมื่นสี่พันส่วน แล้วสร้างสถูปแปดหมื่นสี่พันองค์ทั่วแผ่นดินเสร็จในวันเดียว ตอนที่พระจันทร์ถูกบังพอดี','People say Ashoka opened the old stupas, divided the relics into eighty-four thousand portions, and built eighty-four thousand stupas across the land, all finished on a single day, at the moment of an eclipse.'),
 n:X('ตำนานนี้มาจากอโศกาวทาน ซึ่งเขียนหลายร้อยปีหลังพระเจ้าอโศก ✦ แปดหมื่นสี่พันเป็นตัวเลขแสดงความมากมาย พบในคัมภีร์พุทธหลายเรื่อง เช่นพระธรรมขันธ์ ส่วนในศิลาจารึกจริง พระเจ้าอโศกพูดถึงการขยายสถูปองค์หนึ่งของพระพุทธเจ้าองค์ก่อนเท่านั้น','This legend comes from the Ashokavadana, written centuries after Ashoka ✦. Eighty-four thousand is a number meaning “a great many”, found across Buddhist texts, as in the 84,000 teachings. In his real edicts Ashoka mentions enlarging one stupa, of an earlier Buddha.'),
 o:[opt(X('เชื่อตำนาน','Believe the legend'),S=>{fa20(S,'bud',.5);fx({b:3});return X('คุณนับสถูปตามทางทุกครั้งที่เดินทาง แต่ไม่เคยถึงแปดหมื่น','You count stupas on every journey, but never reach eighty thousand.')}),
    opt(X('คิดว่าคนเล่าเกินจริง','Think the tellers exaggerate'),S=>{fx({kn:2});return X('ตัวเลขใหญ่ขนาดนี้คงหมายความว่า “เยอะมาก” คุณคิดถูก','A number that big must mean “an awful lot”. You are right.')})]}
];
DEC.push(...LEG20);
